 p=root/name;s=p.read_text();assert s.count(old)==count,(name,old[:80],s.count(old));before=hashlib.sha256(s.encode()).hexdigest();s=s.replace(old,new);p.write_text(s);changes[name]={'before_last_patch':before,'after':hashlib.sha256(s.encode()).hexdigest()}
