# Generation selection unloads the previous TTS model; callers serialize complete jobs.
patch('backends/__init__.py','    backend = get_tts_backend_for_engine(engine)\n    if engine in ("qwen", "qwen_custom_voice"):', '    for previous, instance in list(_tts_backends.items()):\n        if previous != engine and instance.is_loaded():\n            instance.unload_model()\n    import gc\n    gc.collect()\n    backend = get_tts_backend_for_engine(engine)\n    if engine in ("qwen", "qwen_custom_voice"):')
# One model operation/inference at a time; avoid unloading a model used by another job.
patch('services/generation.py','from typing import Literal, Optional', 'from typing import Literal, Optional\nimport functools\n\ntts_operation_lock = asyncio.Lock()\ndef single_tts_operation(func):\n    @functools.wraps(func)\n    async def wrapped(*args, **kwargs):\n        async with tts_operation_lock:\n            return await func(*args, **kwargs)\n    return wrapped')
patch('services/generation.py','async def run_generation(', '@single_tts_operation\nasync def run_generation(')
patch('services/generation.py','async def generate_audio_sync(', '@single_tts_operation\nasync def generate_audio_sync(')
patch('backends/__init__.py','def get_model_load_func(config: ModelConfig):','def _get_raw_model_load_func(config: ModelConfig):')
with (root/'backends/__init__.py').open('a') as f:
 f.write("\n\ndef get_model_load_func(config):\n    raw = _get_raw_model_load_func(config)\n    async def guarded():\n        from ..services.generation import tts_operation_lock\n        import asyncio\n        async with tts_operation_lock:\n            if config.engine in TTS_ENGINES:\n                for previous, instance in list(_tts_backends.items()):\n                    if previous != config.engine and instance.is_loaded():\n                        instance.unload_model()\n            result = raw()\n            if asyncio.iscoroutine(result):\n                return await result\n            return result\n    return guarded\n")
for line in ['    from ..backends import get_model_load_func','    from ..backends import unload_model_by_config','    from ..backends import get_model_config, unload_model_by_config']:
 # The last import is also in delete_model; guarding mutation while inference is active is intentional.
 content=(root/'routes/models.py').read_text();count=content.count(line+'\n')
 patch('routes/models.py',line+'\n','    from ..services.generation import tts_operation_lock\n    if tts_operation_lock.locked():\n        raise HTTPException(status_code=409, detail="TTS operation in progress; retry after completion")\n'+line+'\n',count=count)
